{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (0.00) and model shows persistent overestimation.",
    "Reduce forecast peaks by 5-10% after sharp spikes, especially if true outcome shows mean reversion or downward correction.",
    "Apply mean reversion bias correction: if 30-day forecast is > 10% above recent 18-day average, reduce by 10-15%.",
    "Increase downward bias when sentiment shifts to positive (e.g., 0.25) — model may overreact to sentiment, leading to over-optimistic forecasts.",
    "For horizon > 14 days, apply lag correction: if true outcome is consistently below forecast, reduce forecast by 3-5% per day lag.",
    "Avoid overfitting to recent highs: if last 3 days show rising prices, do not extrapolate upward beyond 10% above recent peak."
  ]
}
